svg.script:
(function(){
  var s=document.currentScript, svg=(s&&s.ownerSVGElement)||document.getElementById('sourcing-verificacion');
  if(!svg||!svg.getAnimations||!('IntersectionObserver' in window))return;
  if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  var inView=true;
  function each(fn){svg.getAnimations({subtree:true}).forEach(fn);}
  new IntersectionObserver(function(es){
    var r=es[es.length-1].intersectionRatio;
    if(r===0&&inView){inView=false;each(function(a){a.pause();a.currentTime=0;});}
    else if(r>=0.3&&!inView){inView=true;each(function(a){a.currentTime=0;a.play();});}
  },{threshold:[0,0.3]}).observe(svg);
  svg.style.cursor='pointer';
  svg.addEventListener('click',function(){each(function(a){a.currentTime=0;a.play();});});
})();
